-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6740, 8, 'Mehr Bundesmittel für den Nahverkehr (Regionalisierungsmittel)', 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6741, 8, 'Netz und Betrieb der Deutschen Bahn stärker trennen', 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'gemischt', null, 'bund', null, true, null),
  (6742, 8, 'Überjährige Finanzierung der Schiene über einen Fonds', 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'gemischt', null, 'bund', null, true, null),
  (6743, 8, 'Busführerschein und Berufskraftfahrerqualifikation günstiger und einfacher', 'Senkt eine Hürde für den Berufseinstieg; die Regeln stammen zum großen Teil aus EU-Richtlinien, und Bezahlung und Arbeitszeiten bleiben die Hauptgründe für den Mangel.', 'gemischt', null, 'bund', null, true, null),
  (6744, 8, 'Schienennetz mit mehr Mitteln sanieren und ausbauen', 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'gemischt', null, 'bund', null, true, null),
  (6745, 8, 'Bund steuert die Infrastruktur der Deutschen Bahn wirksamer', 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'offen', null, 'bund', null, true, null),
  (6746, 8, 'Bessere Bezahlung und Arbeitsbedingungen im Nahverkehr (Tariftreue, Personalübernahme)', 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6747, 8, 'Stillgelegte Bahnstrecken reaktivieren', 'Verbessert die Anbindung einzelner ländlicher Orte deutlich, erreicht insgesamt aber nur wenige Menschen; Planung und Bau dauern viele Jahre.', 'gemischt', null, 'bund', null, true, null),
  (6748, 8, 'Verbindliches Mindestangebot an Bus und Bahn (Mobilitätsgarantie)', 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und scheitert derzeit auch am fehlenden Fahrpersonal. Zuständig sind die Länder, der Bund kann über Geld und Rahmenrecht beitragen.', 'offen', null, 'bund', null, true, null),
  (6749, 8, 'Landesweites Bus- und Bahnnetz ausbauen, Takte verdichten', 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'belegt', null, 'land', null, true, null),
  (6750, 8, 'Rufbusse und On-Demand-Verkehre ausbauen', 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'gemischt', null, 'land', null, true, null),
  (6751, 8, 'Verbindliches Mindestangebot (z. B. Stundentakt für jeden Ort, 10-Minuten-Takt in der Stadt)', 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'offen', null, 'land', null, true, null),
  (6752, 8, 'Stillgelegte Strecken und Haltepunkte reaktivieren (Land)', 'Verbessert die Anbindung einzelner Orte deutlich, erreicht insgesamt aber wenige Menschen; Planung und Bau dauern Jahre.', 'gemischt', null, 'land', null, true, null),
  (6753, 8, 'Tariftreue und bessere Bezahlung im Nahverkehr (Land)', 'Bessere Bezahlung macht den Fahrdienst attraktiver und hält Beschäftigte; das Land kann Tariftreue in der Vergabe und bei eigenen Unternehmen durchsetzen, muss die Mehrkosten aber tragen.', 'gemischt', null, 'land', null, true, null),
  (6754, 8, 'Offensive zur Gewinnung und Ausbildung von Fahrpersonal', 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'gemischt', null, 'land', null, true, null),
  (6837, 8, 'Deutschlandticket günstiger machen (Bund gemeinsam mit den Ländern)', 'Ein niedrigerer Preis entlastet alle Fahrgäste direkt; das Neun-Euro-Ticket und die Einführung des Deutschlandtickets haben die Nutzung deutlich erhöht. Jeder Euro weniger kostet Bund und Länder Hunderte Millionen im Jahr, den Preis legen die Länder fest.', 'belegt', null, 'bund', null, true, null),
  (6838, 8, 'Vergünstigtes Deutschlandticket für bestimmte Gruppen (Bund)', 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'belegt', null, 'bund', null, true, null),
  (6839, 8, 'Deutschlandticket mit Landesmitteln erhalten', 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'belegt', null, 'land', null, true, null),
  (6840, 8, 'Vergünstigte Tickets für bestimmte Gruppen (Sozial-, Senioren-, Azubi-, Schülerticket)', 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'belegt', null, 'land', null, true, null),
  (6841, 8, 'Kostenloser Nahverkehr für junge Menschen (Schüler, Auszubildende, unter 21 oder 27 Jahren)', 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'belegt', null, 'land', null, true, null)
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
