  (6761, 8, 12, null, 'Finanzierung des Nahverkehrs mit Ländern und Kommunen dauerhaft stärken', '{801}', 6740, 2, 2, null, 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true, null),
  (6762, 8, 12, null, 'Personalübernahme beim Betreiberwechsel und Tariftreue in Vergabeverfahren', '{803}', 6746, 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true, null),
  (6763, 8, 13, null, 'Überjährige Finanzierung für Schiene und Nahverkehr über den Deutschlandfonds', '{802}', 6742, 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true, null),
  (6764, 8, 13, null, 'Stillgelegte Bahntrassen auf dem Land reaktivieren', '{801}', 6747, 1, 2, null, 'Verbessert die Anbindung einzelner ländlicher Orte deutlich, erreicht insgesamt aber nur wenige Menschen; Planung und Bau dauern viele Jahre.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true, null),
