  (6767, 8, 13, null, 'Marodes Schienennetz mit Hochdruck sanieren', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=50', null, 'gemischt', '2026-09-30', false, true, null),
  (6768, 8, 13, null, 'Bessere Arbeitsbedingungen und gute Bezahlung im Nah- und Fernverkehr', '{803}', 6746, 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=50', null, 'gemischt', '2026-09-30', false, true, null),
  (6769, 8, 14, null, 'Netz und Betrieb bei der Deutschen Bahn trennen', '{802}', 6741, 1, 2, null, 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (6770, 8, 14, null, 'Bus-Führerschein und Berufskraftfahrerqualifikation günstiger machen', '{803}', 6743, 1, 2, null, 'Senkt eine Hürde für den Berufseinstieg; die Regeln stammen zum großen Teil aus EU-Richtlinien, und Bezahlung und Arbeitszeiten bleiben die Hauptgründe für den Mangel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6771, 8, 14, null, 'Starre Linienverkehre durch flexible, bedarfsgerechte Angebote ergänzen', '{801}', null, 1, 2, null, 'On-Demand-Angebote können Lücken im ländlichen Raum schließen, befördern aber wenige Menschen je Fahrt und sind teuer; Angebot und Finanzierung liegen bei Ländern und Kommunen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (6772, 8, 15, null, 'Bahnkonzern in eine GmbH umwandeln, damit der Bund die Infrastruktur wirksam steuern kann', '{802}', 6745, 2, 3, null, 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=46', null, 'offen', '2026-09-30', false, true, null),
  (6773, 8, 15, null, 'Vernachlässigtes Schienennetz ausbauen, Engpässe beseitigen', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=46', null, 'gemischt', '2026-09-30', false, true, null),
  (6774, 8, 15, null, 'ÖPNV im ländlichen Raum bedarfsgerecht ausbauen', '{801}', null, 1, 2, null, 'Benennt das Ziel eines besseren Angebots auf dem Land, aber keinen Weg und keine Finanzierung; Angebot und Bestellung liegen bei Ländern und Kommunen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=40', null, 'offen', '2026-09-30', false, true, null),
  (6775, 8, 16, null, 'Verkehrsträgerübergreifender Infrastrukturfonds nach Schweizer Vorbild', '{802}', 6742, 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'gemischt', '2026-09-30', false, true, null),
