  (6842, 8, 17, null, 'Niedrigere Preise bei Bus und Bahn, Deutschlandticket dauerhaft zu bezahlbarem Preis', '{804}', 6837, 2, 2, null, 'Ein niedrigerer Preis entlastet alle Fahrgäste direkt; das Neun-Euro-Ticket und die Einführung des Deutschlandtickets haben die Nutzung deutlich erhöht. Jeder Euro weniger kostet Bund und Länder Hunderte Millionen im Jahr, den Preis legen die Länder fest.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'belegt', '2026-09-30', false, true, null),
  (6843, 8, 17, null, 'Verfallende Infrastruktur instand setzen, großes Investitionsprogramm', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'gemischt', '2026-09-30', false, true, null),
  (6844, 8, 17, null, 'Bahn mit Netz und Zügen wieder als „Deutsche Bundesbahn“ führen', '{802}', 6745, 2, 3, null, 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=30', null, 'offen', '2026-09-30', false, true, null),
  (6845, 8, 17, null, 'Integriertes, getaktetes Bahn- und ÖPNV-Konzept nach Schweizer Vorbild', '{801}', null, 2, 2, null, 'Ein abgestimmter Taktfahrplan mit verlässlichen Anschlüssen hat in der Schweiz das Angebot auch in der Fläche deutlich verbessert; in Deutschland setzt er Netzausbau und Absprachen mit allen Ländern voraus und dauert Jahre.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=30', null, 'gemischt', '2026-09-30', false, true, null),
  (6846, 8, 12, null, 'Preis des Deutschlandtickets dauerhaft auf aktuellem Niveau halten, mit den Ländern auskömmlich finanzieren', '{804}', null, 1, 2, null, 'Verhindert weitere Preiserhöhungen, senkt den Preis aber nicht; die steigenden Kosten der Verkehrsbetriebe müssen Bund und Länder dann ausgleichen, und den Preis legen die Länder fest.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'belegt', '2026-09-30', false, true, null),
  (6847, 8, 12, null, 'Bundeseinheitlich vergünstigtes Deutschlandticket für soziale Gruppen', '{804}', 6838, 1, 2, null, 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'belegt', '2026-09-30', false, true, null),
  (6848, 8, 13, null, 'Deutschlandticket für 49 Euro', '{804}', 6837, 2, 2, null, 'Ein niedrigerer Preis entlastet alle Fahrgäste direkt; das Neun-Euro-Ticket und die Einführung des Deutschlandtickets haben die Nutzung deutlich erhöht. Jeder Euro weniger kostet Bund und Länder Hunderte Millionen im Jahr, den Preis legen die Länder fest.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'belegt', '2026-09-30', false, true, null),
  (6849, 8, 13, null, 'Azubi-Deutschland-Ticket', '{804}', 6838, 1, 2, null, 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'belegt', '2026-09-30', false, true, null),
  (6850, 8, 16, null, '9-Euro-Ticket sofort wieder einführen', '{804}', null, 3, 1, null, 'Senkt den Preis für alle drastisch und hat 2022 die Nutzung stark erhöht; kostet Bund und Länder zusätzlich viele Milliarden Euro im Jahr, und die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'belegt', '2026-09-30', false, true, null),
  (6851, 8, 16, null, 'Mehrwertsteuer im Nah- und Fernverkehr abschaffen', '{804}', null, 1, 1, null, 'Könnte Fahrpreise um bis zu 7 Prozent senken, wenn die Ersparnis weitergegeben wird; das EU-Mehrwertsteuerrecht erlaubt eine vollständige Befreiung für den Personenverkehr nicht ohne Weiteres.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'offen', '2026-09-30', false, true, null),
  (6852, 8, 11, 'ST', 'Deutschlandticket erhalten, Nutzen für den ländlichen Raum stärken', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', null, 'belegt', '2026-09-30', false, true, null),
  (6853, 8, 12, 'ST', 'Deutschlandticket langfristig bezahlbar absichern', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=42', null, 'belegt', '2026-09-30', false, true, null),
  (6854, 8, 12, 'ST', 'Deutschlandticket für Senioren mit rund 20 Euro im Monat fördern', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=42', null, 'belegt', '2026-09-30', false, true, null),
  (6855, 8, 13, 'ST', 'Vergünstigte Deutschlandtickets für Auszubildende, Freiwillige und Menschen mit geringem Einkommen', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=29', null, 'belegt', '2026-09-30', false, true, null),
  (6856, 8, 14, 'ST', 'Deutschlandticket bleibt Teil des Angebots', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=67', null, 'belegt', '2026-09-30', false, true, null),
  (6857, 8, 15, 'ST', 'Deutschlandticket für alle Schüler', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=201', null, 'belegt', '2026-09-30', false, true, null),
  (6858, 8, 16, 'ST', 'Senioren-Tickets und ermäßigte Tarife für Ältere', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=58', null, 'belegt', '2026-09-30', false, true, null),
  (6859, 8, 16, 'ST', 'Günstiges Jugendticket bis hin zum Nulltarif', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=64', null, 'belegt', '2026-09-30', false, true, null),
  (6860, 8, 17, 'ST', 'Kostenloser Nahverkehr für Schulkinder und Auszubildende', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=33', null, 'belegt', '2026-09-30', false, true, null),
  (6861, 8, 17, 'ST', 'Bezahlbare Sozialtickets für Menschen mit geringem Einkommen', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=33', null, 'belegt', '2026-09-30', false, true, null),
  (6862, 8, 11, 'MV', 'Vergünstigtes Deutschlandticket für junge Menschen bis 27 Jahre', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=124', null, 'belegt', '2026-09-30', false, true, null),
  (6863, 8, 11, 'MV', 'Gratis-Ticket für Auszubildende (wahlweise Führerscheinzuschuss)', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=124', null, 'belegt', '2026-09-30', false, true, null),
  (6864, 8, 12, 'MV', 'Deutschlandticket weiter mit Landesmitteln unterstützen', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=24', null, 'belegt', '2026-09-30', false, true, null),
  (6865, 8, 12, 'MV', 'MV-Jugendticket für Schüler und Auszubildende nach Art des Azubitickets', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=5', null, 'belegt', '2026-09-30', false, true, null),
  (6866, 8, 13, 'MV', 'Deutschlandticket für alle unter 27 kostenfrei', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://gruene-mv.de/?wpdmdl=33772#page=23', null, 'belegt', '2026-09-30', false, true, null),
  (6867, 8, 13, 'MV', 'Deutschlandticket für Menschen mit geringem Einkommen deutlich vergünstigen', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://gruene-mv.de/?wpdmdl=33772#page=23', null, 'belegt', '2026-09-30', false, true, null),
  (6868, 8, 14, 'MV', 'Deutschlandticket mit Landeszuschüssen erhalten', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=61', null, 'belegt', '2026-09-30', false, true, null),
  (6869, 8, 14, 'MV', 'Kostengünstige Azubi-Tickets weiter fördern', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=110', null, 'belegt', '2026-09-30', false, true, null),
  (6870, 8, 15, 'MV', 'Landesweites Azubi-Ticket', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=34', null, 'belegt', '2026-09-30', false, true, null),
  (6871, 8, 16, 'MV', 'Nahverkehr für unter 21-Jährige kostenfrei', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', null, 'belegt', '2026-09-30', false, true, null),
  (6872, 8, 16, 'MV', 'Ermäßigtes Deutschlandticket auch für Studierende auf 29 Euro deckeln', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', null, 'belegt', '2026-09-30', false, true, null),
  (6873, 8, 17, 'MV', 'Kostenloser Nahverkehr für Schulkinder und Auszubildende', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=90', null, 'belegt', '2026-09-30', false, true, null),
  (6874, 8, 12, 'BE', 'Günstigeres Sozialticket', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=47', null, 'belegt', '2026-09-30', false, true, null),
  (6875, 8, 13, 'BE', 'Berliner Klimaticket für 9 Euro im Monat für Menschen mit wenig Geld', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=82', null, 'belegt', '2026-09-30', false, true, null),
  (6876, 8, 16, 'BE', 'Sozialticket wieder auf 9 Euro senken', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=57', null, 'belegt', '2026-09-30', false, true, null),
  (6877, 8, 16, 'BE', 'Preisanstieg bei BVG und S-Bahn stoppen, kostenloses Schülerticket erhalten', '{804}', null, 1, 3, null, 'Verhindert weitere Erhöhungen der Berliner Tarife; für das Deutschlandticket, das viele nutzen, gilt der bundesweit festgelegte Preis weiter. Das Land muss die steigenden Kosten der Verkehrsbetriebe ausgleichen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=8', null, 'offen', '2026-09-30', false, true, null),
  (6878, 8, 17, 'BE', 'Kostenloses Schülerticket in der ganzen Region Berlin-Brandenburg', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=48', null, 'belegt', '2026-09-30', false, true, null),
  (8506, 8, 18, null, 'Öffentlichen Nahverkehr zuverlässig, barrierefrei und dicht getaktet ausbauen', '{801}', null, 2, 2, null, 'Dichtere Takte gewinnen laut Metaanalyse mehr Fahrgäste als Preissenkungen; ohne Betrag bleibt offen, wie viel ankommt. Zuständig sind die Länder, der Bund kann über Geld beitragen, Fahrpersonal fehlt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', 'https://worldtransitresearch.info/research/6475', 'belegt', '2026-10-07', false, true, 'blind'),
  (8507, 8, 18, null, 'Bedarfsgesteuerte Rufbusse und Verzahnung von Nahverkehr und Individualverkehr im ländlichen Raum', '{801}', null, 1, 2, null, 'Rufbusse erreichen auf dem Land mehr Menschen, vor allem abends und am Wochenende; sie kosten je Fahrgast aber ein Vielfaches eines Linienbusses. Zuständig sind die Länder, der Bund kann nur fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', 'https://kommunal.de/on-demand-verkehr-kommunen-aus-finanzierung', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8508, 8, 18, null, 'Deutschlandtakt sowie Ausbau und Modernisierung des Schienennetzes vorantreiben', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', null, 'gemischt', '2026-10-07', false, true, null),
  (8509, 8, 18, null, 'Netz und Betrieb der Bahn entflechten; Bundeskompetenzzentrum steuert die Netzentwicklung', '{802}', 6741, 1, 2, null, 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', null, 'gemischt', '2026-10-07', false, true, null),
  (8510, 8, 18, null, 'Deutschlandticket sichern und weiterentwickeln', '{804}', null, 1, 3, null, 'Die Evaluation zeigt, dass das Ticket genutzt wird und Fahrten vom Auto verlagert; reines Sichern verhindert aber weitere Preiserhöhungen nicht. Der Bund zahlt seinen Anteil bereits.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', 'https://www.bmv.de/SharedDocs/DE/Pressemitteilungen/2026/027-schnieder-evaluation-deutschlandticket.html', 'belegt', '2026-10-07', false, true, 'blind'),
  (8511, 8, 18, null, 'Kosten für Semestertickets übernehmen', '{804}', 6838, 1, 2, null, 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=106', null, 'belegt', '2026-10-07', false, true, null),
  (8627, 8, 18, 'BE', 'Angebot in Außenbezirken und Randlagen durch digitale Rufbusse und autonome Shuttles verbessern; langfristige Finanzierung des Deutschlandtickets unterstützen.', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=31', null, 'gemischt', '2026-10-08', false, true, null),
  (8628, 8, 18, 'BE', 'Modernen Nahverkehrsplan zeitnah umsetzen: Investitionen bündeln, Takte verbessern, neue Tangentialverbindungen mit Tram und Expressbus schaffen.', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=32', null, 'belegt', '2026-10-08', false, true, null),
  (8629, 8, 18, 'BE', 'U-Bahnen vollautomatisieren und bei Tram und Bus digitale Unterstützungssysteme für Fahrpersonal einsetzen, um den Betrieb unabhängiger vom Fachkräftemangel zu machen.', '{803}', null, 1, 2, null, 'Fahrerlose U-Bahnen laufen etwa in Nürnberg und Paris und sparen Fahrpersonal; der Mangel betrifft aber vor allem Bus und Tram, wo Assistenzsysteme niemanden ersetzen. Die Umrüstung dauert Jahre und ist teuer.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=32', 'https://www.trackopedia.com/en/news/all-countries/automated-metro-lines-could-double-in-length-by-2030', 'belegt', '2026-10-08', false, true, 'blind'),
  (8630, 8, 18, 'MV', 'Dichtere Taktung auf stark nachgefragten Hauptachsen, durchgehender Stundentakt auf wichtigen Strecken', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=53', null, 'belegt', '2026-10-08', false, true, null),
  (8631, 8, 18, 'MV', 'Landesweite Mindeststandards für Taktung und Anschlusssicherheit im Nahverkehr', '{801}', 6751, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=54', null, 'offen', '2026-10-08', false, true, null),
  (8632, 8, 18, 'MV', 'Rufbus- und On-Demand-Systeme ausbauen, um ländliche Regionen besser anzubinden', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=54', null, 'gemischt', '2026-10-08', false, true, null),
  (8633, 8, 18, 'MV', 'Kostenloser ÖPNV für Schüler, Auszubildende, Studierende und Freiwilligendienst-Leistende', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=54', null, 'belegt', '2026-10-08', false, true, null),
  (8634, 8, 18, 'ST', 'Landesweite Mindeststandards für Taktung, Anschlusssicherheit und Erreichbarkeit im Nahverkehr', '{801}', 6751, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=90', null, 'offen', '2026-10-08', false, true, null),
  (8635, 8, 18, 'ST', 'Landesweiter Ausbau von Rufbus- und On-Demand-Systemen im ländlichen Raum', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=91', null, 'gemischt', '2026-10-08', false, true, null),
  (8636, 8, 18, 'ST', 'Ausreichend Fahrzeuge und Fahrpersonal für Rufbusse durch Förderung und Qualifizierung sichern', '{803}', 6754, 2, 3, null, 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=91', null, 'gemischt', '2026-10-08', false, true, null),
  (8637, 8, 18, 'ST', 'Landesweit koordiniertes, einkommensabhängig bezuschusstes Sozialticket für das Deutschlandticket', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=96', null, 'belegt', '2026-10-08', false, true, null),
  (8638, 8, 18, 'ST', 'Kostenfreier ÖPNV für Schülerinnen und Schüler landesweit', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=96', null, 'belegt', '2026-10-08', false, true, null),
  (8639, 8, 18, 'ST', 'Gesetzliche Grundlage für eine kommunale Nahverkehrsabgabe, zweckgebunden für Ausbau, Angebot und stabile Preise', '{801}', null, 2, 2, null, 'Eine kommunale Abgabe schafft eigenes Geld für mehr Angebot, wie die Arbeitgeberabgabe in Frankreich zeigt; laut Difu löst sie die Finanzierungsprobleme nicht allein, und es hängt von den Kommunen ab, ob sie sie einführen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=93', 'https://www.zfk.de/mobilitaet/oepnv/mobil-nahverkehr-studie-difu-finanzierung', 'gemischt', '2026-10-08', false, true, 'blind');

